 * @param index
 * @returns
 * @hidden N
*/
scwin.krxpage_pagenavigator_93_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_93.page' }); } scwin.searchList(); };
